figure.sourcecode:
agent-credential = { 1 => 1, ; aee-type 2 => tstr, ; agent_id (see {{ids}}) 3 => COSE_Key, ; agent_key, RFC 9052 Section 7 4 => principal, ; principal 5 => harness, ; harness 6 => model-binding, ; model_binding 7 => validity, ; validity ? 8 => tstr, ; credential_ref: identifier of the ; workload credential (e.g. WIT jti, ; certificate thumbprint) this binds to 9 => tstr, ; logical_agent_id 10 => principal, ; responsible_entity 11 => [ + runtime-identity ], ; runtime_identities 12 => lifecycle-class, ; lifecycle_class ? 20 => tstr ; derived_from (lifecycle derived only) }
runtime-identity = { 1 => tstr, ; identifier 2 => id-scheme, ; scheme 3 => tstr, ; trust_domain 4 => uint, ; valid_from, seconds since Unix epoch 5 => uint ; valid_until } id-scheme = &( wimse: 1, spiffe: 2, did: 3, entra: 4, cloud-native: 5, other: 6 ) lifecycle-class = &( ephemeral: 1, persistent: 2, derived: 3 )
harness = { 1 => tstr, ; name 2 => tstr, ; version ? 3 => digest ; digest of the harness binary/image }
model-binding = { 1 => binding-mode, ? 2 => digest, ; weights_digest (mode 1 only) ? 3 => tstr, ; model_id as named by the provider ? 4 => tstr, ; provider ? 5 => bstr ; tee_evidence: digest of or reference ; to RATS Evidence (mode 3 only) } binding-mode = &( weights-digest: 1, api: 2, api-tee: 3 )
